# What tests/affected.sh runs for a changed path (0.25.2): one rule per
# line, `PREFIX ITEM... # why`; the longest PREFIX a path starts with is
# its rule (a path no rule has gets `*`, the smoke set). An ITEM is
#
#   word      a tests/run.sh FILTER: the cases, suites and checks whose
#             name contains it (`opt_loop`, `gpu`)
#   =NAME     only the case, suite or check NAME (`=lsp`: tests/lsp/run.sh,
#             not every name with lsp in it)
#   @SET      the items of a `set SET ...` line below
#   @self     the changed test itself: tests/run/X.vl (or tests/run/X/...)
#             is case X, tests/examples/X.test is example_X
#   @example  the example the path is in: its tests/examples cases (the
#             ones whose SOURCE is under it), its plain build (`volec
#             examples/X/main.vl -o x`, as example_build does) and
#             example_layout
#   @mentions the cases whose file names the path (a golden image, a C
#             source, a header)
#   !CMD      the command of a `cmd CMD ...` line below, run once from the
#             root (@C: the compiler)
#   +linux    the path is platform-relevant: the plan should also run on
#             aarch64-linux (tests/affected.sh --linux)
#   +broad    the change can alter any program's meaning: the plan is
#             broad, and --list says so
#   ?PREFIX   the rest of the rule only when no other changed path starts
#             with PREFIX (a generated file, tested through its source's
#             rules)
#
# Suites that do not take -O (query, lsp, guide, ...) and the cases that
# must fail to compile (an ERROR directive: about half of them) run at
# the first level only; the other cases, gpu and arch-gen at every level
# asked for.
# Keep a rule's items the tests that would fail first; tier 3 (the
# integrator's full suite and gate) catches the rest.

# ---- sets ----
# smoke: one wide, cheap slice of the language and the toolchain (about
# 220 cases): what an unknown path or a small change gets.
set smoke   arith_ ctrl_ enum_ match_ str_ float_ trait_ err_syntax err_type sem_core_idx opt_inline opt_gvn opt_licm =example_helloworld =example_factorial =example_md5_abc =example_life =readme_sync
# broad: every program-level case (the language and std as programs see
# them) and the suites that compile programs; not the tools' suites.
set broad   +broad sem_ err_ own_ std_ opt_ iter_ closure_ generic_ example_ =std-own =std-moves =own-try =guide =book
# codegen: what the back end and the optimizer change.
set codegen @smoke opt_ arith_ float_ cast_ conv_ abi_ vector_ iter_ array_ slice_ checkalloc_ example_ !fuzz

cmd fuzz    tests/fuzz/run.sh -c @C -n 40
cmd abi     tests/abi/run.sh -c @C -n 30
# (0.25.5) the gate's compile-cost row: a hello world, std_heavy and a check
# of compiler/src, in instructions, against the previous release (@P; about
# half a minute): std reaches every program (0.25.4's 1.46x hello world was
# caught only by hand), the front end and the optimizer every compile
cmd cost    tests/compile_cost.sh -c @C -p @P
cmd tmgrammar python3 editors/vscode/test/tmgrammar.py

# ---- the compiler ----
compiler/src/front/            @broad +linux !cost             # the front end decides what every program means
compiler/src/front/own/        @broad =own-try +linux !cost    # ownership and moves: every program
compiler/src/front/stdsrc.vl   ?compiler/std/ @std !cost       # generated from compiler/std: its rules, or @std when changed alone
compiler/src/front/cimport/    @smoke cimport ffi extern abi_ example_c- !abi =lsp +linux !cost   # C imports: headers, layouts
compiler/src/front/embed/      @smoke embed str_text_block =embed-checks =lsp =query =wgsl =gpu !cost   # include_str, include_bytes; (0.26.0) embed wgsl blocks, their check
compiler/src/front/lexer/embedded.vl @broad =fmt fmt_ embed str_text_block =embed-checks =query =refactor !cost   # (0.26.0) an embedded block's text, one token
compiler/src/front/cpp/        @smoke cimport ffi extern example_c- =lsp +linux !cost             # the C preprocessor
compiler/src/front/contracts/  @smoke contract !cost           # contracts (requires/ensures)
compiler/src/front/effects/    @smoke eff =example_effects-effect-bounds =example_effects-effects-for-agents =example_effects-pure-and-no-alloc =example_effects-trait-purity !cost
compiler/src/front/closures/   @smoke closure_ cl_ iter_ !cost
compiler/src/front/derive/     @smoke derive_ !cost
compiler/src/front/parser/     @broad =fmt fmt_ embed !cost    # the grammar: every program, and fmt (and include_str)
compiler/src/front/lexer/      @broad =fmt fmt_ str_text_block err_text_block =embed-checks !cost
compiler/src/front/tests/      @smoke test !cost               # `volec test`
compiler/src/middle/           @codegen !cost                  # the optimizer: every -O1/-O2 program
compiler/src/middle/vectorize/ @smoke =perf opt_vector vector_ opt_slp opt_loop opt_unroll opt_iter iter_ =arch-gen !fuzz !cost
compiler/src/middle/slp.vl     @smoke opt_slp vector_ opt_vector !fuzz !cost
compiler/src/middle/range/     @smoke opt_range range !fuzz !cost
compiler/src/middle/checkalloc.vl @smoke checkalloc allocators !cost
compiler/src/middle/unsafecheck.vl @smoke unsafe !cost
compiler/src/middle/effects_verify.vl @smoke eff !cost
compiler/src/middle/profile.vl @smoke opt_profile !cost
compiler/src/middle/threads.vl @smoke thread sync mutex atomic +linux !cost
compiler/src/middle/parallel.vl @smoke thread sync mutex atomic parallel +linux !cost
compiler/src/middle/lower/     @broad @codegen !cost           # lowering: every -O1/-O2 program
compiler/src/back/             @codegen =link +linux     # code generation for every target
compiler/src/back/objfile/     @smoke =link =example_build +linux   # the object files and the linker
compiler/src/back/abi.vl       @codegen abi_ ffi extern example_c- !abi +linux
compiler/src/back/enc_x86.vl   =arch-enc x86 cross       # x86-64 (no x86 rows run now)
compiler/src/back/mc_x86_64/   =arch-enc x86 cross
compiler/src/back/codecache/   @smoke =example_build =embed-checks     # the code cache (the suite runs without it; the gate's suite-O2 with it)
compiler/src/gen0/             @codegen                  # -O0's code generator and every level's driver
compiler/src/arch/             @smoke arch =arch-gen =arch-enc +linux
compiler/arch/                 @smoke arch =arch-gen =arch-enc +linux
compiler/src/base/             @smoke                    # shared pieces
compiler/src/base/diag.vl      @smoke err_ =query        # how every diagnostic prints
compiler/src/base/json.vl      @smoke =lsp =query
compiler/src/base/timer.vl     @smoke =perf +linux       # --time-passes, its counters
compiler/src/base/target.vl    @smoke cross +linux
compiler/src/cli/              @smoke cli_ =example_cli =example_cli_bad =example_cli_help =example_cli_unknown =query =walkthrough
compiler/src/main.vl           @smoke
compiler/src/guide/            =guide                    # `volec guide`'s text and search
compiler/guide/                =guide                    # the guide's topics, every example compiled
compiler/src/tools/            @smoke =query =refactor =walkthrough =cachediff   # the agent tools
compiler/src/tools/lsp/        =lsp                      # the language server's sessions
compiler/src/tools/query/      =query =walkthrough =embed-checks =cachediff
compiler/src/tools/query_text.vl =query
compiler/src/tools/refactor_mod/ =refactor
compiler/src/tools/refactor_move/ =refactor
compiler/src/tools/refactor_shape/ =refactor
compiler/src/tools/edit/       =refactor =query =cachediff
compiler/src/tools/patch/      =refactor =cachediff
compiler/src/tools/rewrite/    =refactor
compiler/src/tools/fmt/        =fmt fmt_
compiler/src/tools/fix/        =refactor fix_ =own-try
compiler/src/tools/fiximports.vl =refactor fix
compiler/src/tools/fixunsafe.vl =refactor fix unsafe
compiler/src/tools/explain/    =query err_017            # `volec explain`
compiler/src/tools/probe/      =query =walkthrough
compiler/src/tools/reduce/     =query =walkthrough
compiler/src/tools/testrun/    =query =walkthrough test
compiler/README.md             @none                     # prose

# ---- the standard library ----
compiler/std/                  @std +linux !cost               # std: every program reads it
compiler/std/gpu/              gpu =wgsl =std-own =std-moves =example_gpu-life !cost   # std::gpu: Metal cases, WGSL, the gpu examples (gpu matches example_gpu-*)
compiler/std/window/           =window =voltty_render =std-own =std-moves example_gpu- =example_c-mixed-build_window !cost
compiler/std/objc/             gpu =window =std-own !cost
compiler/std/sync/             @std thread sync mutex atomic +linux !cost
compiler/std/sys/              @std sys_ io_ +linux !cost
compiler/std/io/               @std io_ =example_httpd +linux !cost
compiler/std/collections/      @std collection hash map vec btree !cost
compiler/std/embed.sh          @std !cost
compiler/std/index.awk         @std =guide !cost
set std     @smoke std_ =std-own =std-moves =guide iter_ str_ slice_ alloc collection example_algorithms

# ---- tests and the runner ----
tests/run/                     @self
tests/examples/                @self
tests/golden/                  @mentions
tests/c/                       @mentions
tests/cimport/                 @mentions cimport
tests/run.sh                   =runner runner_ @smoke =example_layout =example_build =query +linux   # the runner itself
tests/expect.awk               =runner runner_
tests/directives.awk           =runner runner_ @smoke
tests/watchdog.sh              =runner runner_
tests/budget.sh                =runner runner_
tests/ppmdiff.sh               =runner runner_ @mentions
tests/affected.sh              =runner                   # this tool (its --list is the check)
tests/affected.map             =runner
tests/runner/                  =runner runner_
tests/embed/                   =embed-checks
tests/cachediff/               =cachediff
tests/stdpos.awk               =stdpos =query =refactor =walkthrough =book =lsp   # std's positions compared normalized (0.25.3), (0.25.5) the LSP's too
tests/stdkeep.sh               =stdpos =query =refactor =walkthrough =lsp   # (0.25.5) what the runners' -u write
tests/stdpos/                  =stdpos
tests/lsp/                     =lsp
tests/query/                   =query =stdpos =cachediff
tests/refactor/                =refactor =stdpos =cachediff
tests/guide/                   =guide
tests/book/                    =book
tests/fmt/                     =fmt
tests/walkthrough/             =walkthrough =stdpos
tests/wgsl/                    =wgsl
tests/gpu/                     =gpu
tests/voltty/                  =voltty
tests/voltty-render/           =voltty_render
tests/window/                  =window
tests/own-try/                 =own-try
tests/link/                    =link +linux
tests/perf/                    =perf +linux
tests/arch/                    =arch-gen =arch-enc
tests/std/own.sh               =std-own
tests/std/moves.sh             =std-moves
tests/std/                     =std-own =std-moves @smoke
tests/fuzz/                    !fuzz
tests/abi/                     !abi +linux
tests/agent-eval/              @none                     # the eval harness, not run by the suite

# ---- examples, docs, tools ----
examples/                      @example
examples/tools/                =walkthrough              # the tools' walkthroughs (README sessions)
examples/README.md             =example_layout
book/                          =book
README.md                      =readme_sync =example_layout
AGENTS.md                      @none                     # agents' instructions (prose)
CLAUDE.md                      @none
docs/                          @none                     # prose: no test reads it
docs/lsp.md                    =lsp                      # tests/lsp/run.sh reads it
docs/design/gpu.md             =gpu =wgsl
docs/design/arch.md            =arch-gen
docs/design/value-semantics.md =own-try
editors/                       =lsp                      # the editor extension talks to the server (its own tests: npm test)
editors/vscode/                =lsp !tmgrammar           # (0.26.0) its grammars (vole's, wgsl's injected into blocks): tmgrammar.py
tools/agent-hooks/             =hooks
tools/wgslc/                   =wgsl
tools/premerge.sh              @none                     # run it: tier 2 does
tools/git-hooks/               =hooks                    # run by every commit; its cases (0.25.3)
.gitattributes                 =hooks                    # stdsrc.vl's merge driver (tools/git-hooks/test-stdsrc.py)
tools/unsafe-diff-check.py     =hooks                    # the commit hook's unsafe check
tools/agent-feedback           @none
bootstrap/                     @smoke                    # the build itself is tier 1's check; then a smoke slice
bootstrap/aarch64-linux-check.sh @smoke +linux
bootstrap/ci/                  @smoke +linux
seed/                          @smoke                    # the seed only builds the chain
.claude/                       @none                     # agents' notes and briefs
feedbacks/                     @none
*                              @smoke                    # anything else: the smoke set, never nothing
